public boolean refreshTTL(RefreshOfferMessage refreshTTLMessage, @Nullable NodeAddress sender) {
  try {
    ByteArray hashOfPayload = new ByteArray(refreshTTLMessage.getHashOfPayload());
    ProtectedStorageEntry storedData = map.get(hashOfPayload);
    if (storedData == null) {
      log.debug("We don't have data for that refresh message in our map. That is expected if we missed the data publishing.");
      return false;
    }
    ProtectedStorageEntry storedEntry = map.get(hashOfPayload);
    ProtectedStorageEntry updatedEntry = new ProtectedStorageEntry(storedEntry.getProtectedStoragePayload(), storedEntry.getOwnerPubKey(), refreshTTLMessage.getSequenceNumber(), refreshTTLMessage.getSignature(), this.clock);
    if (!hasSequenceNrIncreased(updatedEntry.getSequenceNumber(), hashOfPayload)) return false;
    if (!updatedEntry.isValidForAddOperation()) return false;
    map.put(hashOfPayload, updatedEntry);
    sequenceNumberMap.put(hashOfPayload, new MapValue(updatedEntry.getSequenceNumber(), this.clock.millis()));
    requestPersistence();
    broadcaster.broadcast(refreshTTLMessage, sender);
    return true;
  } catch (NullPointerException e) {
    log.debug("NullPointerException in refreshTTL: " + e.getMessage());
    return false;
  } catch (ClassCastException e) {
    log.debug("ClassCastException in refreshTTL: " + e.getMessage());
    return false;
  } catch (IllegalArgumentException e) {
    log.debug("IllegalArgumentException in refreshTTL: " + e.getMessage());
    return false;
  } catch (SignatureException e) {
    log.debug("SignatureException in refreshTTL: " + e.getMessage());
    return false;
  } catch (UnsupportedOperationException e) {
    log.debug("UnsupportedOperationException in refreshTTL: " + e.getMessage());
    return false;
  } catch (DateTimeException e) {
    log.debug("DateTimeException in refreshTTL: " + e.getMessage());
    return false;
  }
}
